/* 盒模型取值 */
shape-outside: margin-box;
shape-outside: border-box;
shape-outside: padding-box;
shape-outside: content-box;

/* 形状函数取值 */
shape-outside: circle(50%);
shape-outside: ellipse(100px 80px);
shape-outside: inset(10px 10px 10px 10px round 10px);
shape-outside: polygon(0 0, 100% 0, 100% 100%);

/* 形状函数 + 参考框组合 */
shape-outside: circle(50%) border-box;

/* 图片取值 */
shape-outside: url("image.png");
shape-outside: linear-gradient(45deg, white 150px, transparent 150px);

content.content:
const { useId, useState } = React;

const TRIANGLE = "polygon(50% 0%, 100% 100%, 0% 100%)";
const SOFT_STOPS = [0.3, 0.7];
// 方形参考框里 radial-gradient 默认尺寸 farthest-corner 的半径
const cornerRadius = size => (size * Math.SQRT2) / 2;

// 三类取值各自固定一套盒模型，类别内只改 shape-outside，控制变量
const BOXES = {
  "shape-box": { size: 96, margin: [12, 12, 12, 12], border: 6, padding: 10, radius: 20 },
  "basic-shape": { size: 120, margin: [0, 24, 24, 0], border: 0, padding: 0, radius: 0 },
  image: { size: 120, margin: [0, 24, 24, 0], border: 0, padding: 0, radius: 0 },
};

// 外形描述都以 margin-box 左上角为原点
const roundRect = (inset, outer, radius) => ({ kind: "rect", x: inset, y: inset, w: outer - inset * 2, h: outer - inset * 2, r: Math.max(radius, 0) });

const OPTIONS = {
  "shape-box": [
    { label: "none", value: "none", note: "不设置时按 margin-box 矩形环绕，忽略圆角", shape: () => roundRect(0, 152, 0) },
    { label: "margin-box", value: "margin-box", note: "最外层，圆角随 margin 一起外扩", shape: () => roundRect(0, 152, 32) },
    { label: `border-box`, value: `border-box`, note: "从 border 外缘算起，margin 区域开放给文字", shape: () => roundRect(12, 152, 20) },
    { label: "padding-box", value: "padding-box", note: "文字可以进入 border 区域", shape: () => roundRect(18, 152, 14) },
    { label: "content-box", value: "content-box", note: "文字可以进入 border 与 padding", shape: () => roundRect(28, 152, 4) },
  ],
  "basic-shape": [
    { label: "circle()", value: "circle(50%) border-box", clip: "circle(50%)", note: "半径 50%，参考框为 border-box", shape: () => ({ kind: "ellipse", cx: 60, cy: 60, rx: 60, ry: 60 }) },
    { label: "ellipse()", value: "ellipse(50% 35%) border-box", clip: "ellipse(50% 35%)", note: "水平半径 50%，垂直半径 35%", shape: () => ({ kind: "ellipse", cx: 60, cy: 60, rx: 60, ry: 42 }) },
    { label: "polygon()", value: `${TRIANGLE} border-box`, clip: TRIANGLE, note: "三个顶点围成的三角形", shape: () => ({ kind: "polygon", points: "60,0 120,120 0,120" }) },
    { label: "inset()", value: "inset(10px round 20px) border-box", clip: "inset(10px round 20px)", note: "四边内缩 10px，带 20px 圆角", shape: () => roundRect(10, 120, 20) },
  ],
  image: [
    {
      label: "线性硬边",
      value: "linear-gradient(135deg, var(--tau-accent) 60%, transparent 60%)",
      note: "左上 60% 不透明，排斥文字；右下透明，文字可以进入",
      shape: () => ({ kind: "polygon", points: "0,0 144,0 144,28.8 28.8,144 0,144" }),
    },
    {
      label: "径向硬边",
      value: "radial-gradient(circle, var(--tau-accent) 50%, transparent 50%)",
      note: "中心 50% 不透明，外圈透明",
      shape: () => ({ kind: "ellipse", cx: 72, cy: 72, rx: cornerRadius(144) / 2, ry: cornerRadius(144) / 2 }),
    },
    {
      label: "径向柔边",
      value: `radial-gradient(circle, var(--tau-accent) ${SOFT_STOPS[0] * 100}%, transparent ${SOFT_STOPS[1] * 100}%)`,
      note: "30% 到 70% 之间 alpha 逐渐降为 0，阈值决定边界落在哪一圈",
      // alpha 从 30% 处的 1 线性降到 70% 处的 0，alpha = 阈值的那一圈就是边界
      shape: threshold => {
        const radius = (SOFT_STOPS[0] + (SOFT_STOPS[1] - SOFT_STOPS[0]) * (1 - threshold)) * cornerRadius(144);
        return { kind: "ellipse", cx: 72, cy: 72, rx: radius, ry: radius };
      },
    },
  ],
};
const CATEGORIES = Object.keys(OPTIONS);

const TEXT =
  "这是一段用来演示文字环绕效果的示例文本。shape-outside 让浮动元素周围的行内内容按照指定的形状排列，而不是默认的矩形边界。切换不同的取值，可以直观看到文字如何沿着不同的形状边缘流动。这在杂志风格排版、创意页面设计中很常见，能打破网页方方正正的布局，让文字与图形产生更自然的互动。文字会尽量填满形状外部的可用空间，呈现更有机的排版效果。拖动 shape-margin，文字与形状之间会留出间距，但这段间距永远不会越过 margin-box。";

const ShapeElement = ({ shape, ...props }) => {
  if (shape.kind === "rect") return <rect x={shape.x} y={shape.y} width={shape.w} height={shape.h} rx={shape.r} {...props} />;
  if (shape.kind === "ellipse") return <ellipse cx={shape.cx} cy={shape.cy} rx={shape.rx} ry={shape.ry} {...props} />;
  return <polygon points={shape.points} {...props} />;
};

const Pill = ({ active, onClick, children, mono }) => (
  <button
    type="button"
    aria-pressed={active}
    onClick={onClick}
    className={`cursor-pointer rounded-full border px-3 py-1 text-tau-sm transition-colors ${mono ? "font-tau-mono" : ""} ${
      active ? "border-accent bg-accent-soft text-accent-text" : "border-line-1 bg-surface text-ink-2 hover:bg-hover"
    }`}
  >
    {children}
  </button>
);

const Slider = ({ label, value, min, max, step = 1, onChange, format }) => (
  <label className="flex min-w-[220px] flex-1 items-center gap-3">
    <span className="shrink-0 font-tau-mono text-tau-sm text-ink-2">{label}</span>
    <input
      type="range"
      min={min}
      max={max}
      step={step}
      value={value}
      onChange={event => onChange(Number(event.target.value))}
      className="cb-range h-1.5 min-w-0 flex-1 cursor-pointer"
    />
    <span className="w-12 shrink-0 text-right font-tau-mono text-tau-sm text-ink-1">{format(value)}</span>
  </label>
);

const Mark = ({ children }) => <span className="rounded-tau-sm bg-accent-soft px-0.5 text-accent-text">{children}</span>;

const Component = () => {
  const maskId = `cb-so-${useId().replace(/[^\w-]/g, "")}`;
  const [category, setCategory] = useState("shape-box");
  const [index, setIndex] = useState(2);
  const [shapeMargin, setShapeMargin] = useState(0);
  const [threshold, setThreshold] = useState(0);
  const [clip, setClip] = useState(true);

  const box = BOXES[category];
  const option = OPTIONS[category][index] ?? OPTIONS[category][0];
  const shape = option.shape(threshold);
  const [mt, mr, mb, ml] = box.margin;
  const borderBox = box.size + (box.border + box.padding) * 2;
  const outerW = borderBox + ml + mr;
  const outerH = borderBox + mt + mb;
  const isNone = option.value === "none";
  const clipPath = category === "basic-shape" && clip ? option.clip : undefined;

  const floatStyle = {
    float: "left",
    position: "relative",
    width: box.size,
    height: box.size,
    margin: box.margin.map(value => `${value}px`).join(" "),
    padding: box.padding,
    borderWidth: box.border,
    borderRadius: box.radius,
    shapeOutside: option.value,
    shapeMargin: `${shapeMargin}px`,
    shapeImageThreshold: String(threshold),
    clipPath,
  };

  const chooseCategory = next => {
    setCategory(next);
    setIndex(next === "shape-box" ? 2 : 0);
  };

  const cssLines = [
    ["float: left;"],
    [`width: ${box.size}px; height: ${box.size}px;`],
    [`margin: ${floatStyle.margin};`],
    ...(box.border ? [[`border: ${box.border}px solid; padding: ${box.padding}px; border-radius: ${box.radius}px;`]] : []),
    ["shape-outside: ", <Mark key="so">{option.value}</Mark>, ";"],
    ["shape-margin: ", <Mark key="sm">{shapeMargin}px</Mark>, ";"],
    ...(category === "image" ? [["shape-image-threshold: ", <Mark key="th">{threshold}</Mark>, ";"]] : []),
    ...(category === "basic-shape"
      ? [clipPath ? ["clip-path: ", <Mark key="cp">{clipPath}</Mark>, ";"] : [<span key="c" className="text-ink-3">/* 未设置 clip-path，元素外观仍是矩形 */</span>]]
      : []),
  ];

  return (
    <div className="flex flex-col gap-3">
      <style>{`
        @scope {
          .cb-range { accent-color: var(--tau-accent); }
          .cb-so-float { border-style: solid; border-color: var(--tau-accent); background-clip: padding-box; }
        }
      `}</style>
      <div className="flex flex-wrap items-center gap-2">
        {CATEGORIES.map(name => (
          <Pill key={name} mono active={category === name} onClick={() => chooseCategory(name)}>
            {name === "image" ? "<image>" : `<${name}>`}
          </Pill>
        ))}
      </div>
      <div className="flow-root overflow-hidden rounded-tau-md border border-line-1 p-4 pl-5 pt-5 text-tau-body leading-[1.8] text-ink-2">
        <div
          className={`cb-so-float ${category === "shape-box" ? "bg-accent-soft" : category === "basic-shape" ? "bg-accent" : ""}`}
          style={floatStyle}
        >
          {category === "image" && (
            <div
              className="pointer-events-none absolute left-0 top-0 opacity-40"
              style={{ width: outerW, height: outerH, backgroundImage: option.value }}
            />
          )}
          <svg
            className="pointer-events-none absolute overflow-visible"
            style={{ left: -(ml + box.border), top: -(mt + box.border), width: outerW, height: outerH }}
            viewBox={`0 0 ${outerW} ${outerH}`}
          >
            <defs>
              <mask id={maskId} maskUnits="userSpaceOnUse" x="0" y="0" width={outerW} height={outerH}>
                <rect x="0" y="0" width={outerW} height={outerH} fill="white" />
                <ShapeElement shape={shape} fill="black" />
              </mask>
            </defs>
            <rect x="0.5" y="0.5" width={outerW - 1} height={outerH - 1} className="fill-none stroke-ink-3" strokeDasharray="2 3" />
            {category === "shape-box" && (
              <rect
                x={ml + box.border + box.padding}
                y={mt + box.border + box.padding}
                width={box.size}
                height={box.size}
                rx="4"
                className="fill-none stroke-accent"
                strokeOpacity="0.5"
                strokeDasharray="2 3"
              />
            )}
            {!isNone && shapeMargin > 0 && (
              <ShapeElement shape={shape} mask={`url(#${maskId})`} className="fill-none stroke-accent" strokeOpacity="0.2" strokeWidth={shapeMargin * 2} strokeLinejoin="round" />
            )}
            <ShapeElement shape={shape} className="fill-none stroke-accent" strokeWidth="1.5" strokeDasharray="5 3" />
          </svg>
        </div>
        {TEXT}
      </div>
      <div className="flex flex-wrap items-center gap-2">
        {OPTIONS[category].map((item, itemIndex) => (
          <Pill key={item.label} mono={category !== "image"} active={itemIndex === index} onClick={() => setIndex(itemIndex)}>
            {item.label}
          </Pill>
        ))}
        {category === "basic-shape" && (
          <span className="ml-auto">
            <ui.Switch size="sm" checked={clip} onCheckedChange={setClip} label="同步 clip-path" />
          </span>
        )}
      </div>
      <div className="flex flex-wrap items-center gap-x-6 gap-y-2">
        <Slider label="shape-margin" value={shapeMargin} min={0} max={24} onChange={setShapeMargin} format={value => `${value}px`} />
        {category === "image" && (
          <Slider label="threshold" value={threshold} min={0} max={0.95} step={0.05} onChange={setThreshold} format={value => value.toFixed(2)} />
        )}
      </div>
      <div className="flex flex-wrap items-center gap-x-4 gap-y-1 text-tau-meta text-ink-3">
        <span className="flex items-center gap-1.5"><span className="h-0 w-4 border-t-2 border-dashed border-accent" />环绕边界</span>
        <span className="flex items-center gap-1.5"><span className="h-2 w-4 rounded-tau-sm bg-accent-soft" />shape-margin</span>
        <span className="flex items-center gap-1.5"><span className="h-0 w-4 border-t border-dashed border-ink-3" />margin-box 上限</span>
        <span className="text-ink-2">{isNone && shapeMargin > 0 ? "none 没有形状，shape-margin 不生效" : option.note}</span>
      </div>
      <pre className="m-0 overflow-x-auto rounded-tau-md border border-line-1 bg-surface p-3 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
        {cssLines.map((line, lineIndex) => (
          <div key={lineIndex}>{line}</div>
        ))}
      </pre>
    </div>
  );
};
